def mark_pruned_sessions(apps, schema_editor):
    """Sessions pruned before this flag existed: merged, a sales or gym section saved rows, but none are left."""
    Session = apps.get_model("scraper", "Session")
    SectionResult = apps.get_model("scraper", "SectionResult")
    SalesRecord = apps.get_model("scraper", "SalesRecord")
    GymMember = apps.get_model("scraper", "GymMember")
    had_rows = set(SectionResult.objects.filter(report__in=("sales", "gym"), row_count__gt=0)
                   .values_list("session_id", flat=True).distinct())
    still = set(SalesRecord.objects.values_list("session_id", flat=True).distinct()) | \
        set(GymMember.objects.values_list("session_id", flat=True).distinct())
    pruned = [pk for pk in Session.objects.filter(merged_into_masters=True).values_list("pk", flat=True)
              if pk in had_rows and pk not in still]
    for i in range(0, len(pruned), 500):
        Session.objects.filter(pk__in=pruned[i:i + 500]).update(rows_pruned=True)


